// ToolBox for Windows: one window around the app page, plus what a browser cannot do (folders, printers, a safe close).
// The shop's data stays in Windows' app-data folder (%APPDATA%\ToolBox) and is kept when the app is updated or removed.
const { app, BrowserWindow, ipcMain, dialog, shell, Menu, session, Notification, nativeImage } = require('electron');
const path = require('path'), fs = require('fs');
// the starter (launcher.js) says which Windows part runs: the installed one or a newer one from the internet (app-data folder).
// The app's own files (page, icons) are always in the installation folder.
const TB = global.__tbShell || { launcher: 0, bundled: '000000000000', build: '000000000000', using: 'bundled', root: __dirname, ok() {} };
const ROOT = TB.root || __dirname;

// one copy of the app at a time (two windows writing the same data is how data gets mixed up)
if (!app.requestSingleInstanceLock()) { app.quit(); }
if (process.platform === 'win32') app.setAppUserModelId('app.toolbox.pos');   // Windows shows the app's own name and icon on its notifications

const DOCS = () => path.join(app.getPath('documents'), 'ToolBox');
const BACKUPS = () => path.join(DOCS(), 'Backups');
const ensure = d => { fs.mkdirSync(d, { recursive: true }); return d; };
// only plain file names inside a folder the app was given (no "..\" tricks)
const inside = (dir, name) => { const n = path.basename(String(name)); if (!n || n !== String(name)) throw new Error('badName'); return path.join(dir, n); };

let win = null, closing = false;
function create() {
  Menu.setApplicationMenu(null);   // no menu bar: F5, F12, Ctrl+R… belong to the app (F5 = pay and choose customer)
  win = new BrowserWindow({
    width: 1280, height: 800, minWidth: 1024, minHeight: 640, show: false, title: 'ToolBox',
    backgroundColor: '#F5F5F7', icon: path.join(ROOT, 'build', 'icon.png'), autoHideMenuBar: true,
    webPreferences: { preload: path.join(__dirname, 'preload.js'), contextIsolation: true, nodeIntegration: false, sandbox: true, spellcheck: false }
  });
  win.loadFile(pickPage());
  win.once('ready-to-show', () => { win.maximize(); win.show(); });
  win.webContents.once('did-finish-load', () => { try { TB.ok(); } catch (e) { /* an older starter */ } });   // this Windows part works: kept
  // links (WhatsApp, a web page) open in the normal browser, never inside the app
  win.webContents.setWindowOpenHandler(({ url }) => { if (/^https?:|^mailto:|^tel:/i.test(url)) shell.openExternal(url); return { action: 'deny' }; });
  win.webContents.on('will-navigate', (e, url) => { if (!url.startsWith('file:')) { e.preventDefault(); if (/^https?:/i.test(url)) shell.openExternal(url); } });
  // a backup / Excel file saved from the app goes straight to Documents\ToolBox (backups) or Downloads, no question
  session.defaultSession.on('will-download', (e, item) => {
    const name = item.getFilename(), dir = /^toolbox.*\.json$/i.test(name) ? ensure(BACKUPS()) : app.getPath('downloads');
    item.setSavePath(path.join(dir, name));
  });
  // closing: the page writes today's data (and the daily backup) first, then the window goes
  // the page first asks (in its own style) whether to close; "no" keeps the window. A page that does not answer at all (stuck)
  // is closed anyway after a few seconds, and saving never holds the window open for ever.
  let asking = false;
  win.on('close', e => {
    if (closing) return;
    e.preventDefault(); if (asking) return; asking = true;
    const done = () => { closing = true; if (win && !win.isDestroyed()) win.destroy(); };
    let t = setTimeout(done, 5000);   // no sign of life from the page: it is stuck, so the window goes
    const off = () => { ipcMain.removeAllListeners('app-close-seen'); ipcMain.removeAllListeners('app-close-saving'); ipcMain.removeAllListeners('app-close-ok'); ipcMain.removeAllListeners('app-close-no'); };
    ipcMain.once('app-close-seen', () => { clearTimeout(t); t = null; });
    ipcMain.once('app-close-saving', () => { clearTimeout(t); t = setTimeout(done, 120000); });
    ipcMain.once('app-close-ok', () => { clearTimeout(t); off(); asking = false; done(); });
    ipcMain.once('app-close-no', () => { clearTimeout(t); off(); asking = false; });
    win.webContents.send('app-close');
  });
  win.on('closed', () => { win = null; });
}
app.on('second-instance', () => { if (win) { if (win.isMinimized()) win.restore(); win.focus(); } });
app.whenReady().then(create);

// ---- ToolBox on the phones (Settings → iPhone): the shop's own network only — a fixed name, the shop's certificate, the app over https
const Mobile = require('./mobile');
let mob = null;
// the phones get the same app page this window runs (read again only when the file changed)
let pageCache = null;
const pageNow = () => { try { const st = fs.statSync(curPage), stamp = curPage + ':' + st.mtimeMs + ':' + st.size;
  if (!pageCache || pageCache.stamp !== stamp) pageCache = { stamp, text: fs.readFileSync(curPage, 'utf8') }; return pageCache; } catch (e) { return null; } };
// a phone's request (sync, a new version): the page checks who it is and answers (2 minutes at most)
let apiSeq = 0; const apiWaits = new Map();
ipcMain.on('mob:api-reply', (e, id, r) => { const w = apiWaits.get(id); if (w) { apiWaits.delete(id); w(r); } });
const phoneApi = (name, d) => new Promise(res => {
  if (!win || win.isDestroyed()) return res({ ok: false, msg: 'ئەپەکە لەسەر کۆمپیوتەر داخراوە' });
  const id = ++apiSeq; apiWaits.set(id, res);
  setTimeout(() => { if (apiWaits.has(id)) { apiWaits.delete(id); res({ ok: false, msg: 'کۆمپیوتەرەکە وەڵامی نەدایەوە' }); } }, 120000);
  win.webContents.send('mob:api', id, name, d);
});
const mobile = () => mob || (mob = Mobile.create(app.getPath('userData'), pageNow, phoneApi));
ipcMain.handle('mob:status', () => mobile().status());
ipcMain.handle('mob:set', (e, on) => { if (!on && wf && wf.wantOn) wf.set(false); return on ? mobile().start() : mobile().stop(); });
ipcMain.handle('mob:icons', (e, set) => mobile().icons(set));
ipcMain.handle('mob:identity', () => mobile().identity());
ipcMain.handle('mob:setIdentity', (e, x) => mobile().setIdentity(x));
app.whenReady().then(() => { try { if (mobile().wantOn) mobile().start().catch(() => {}); } catch (e) { /* switched on again from Settings */ } });
app.on('before-quit', () => { if (mob) mob.close(); if (wf) wf.close(); });
// ToolBox Wi-Fi: this computer's own Wi-Fi network for the shop's devices (no internet needed)
const Wifi = require('./wifi');
let wf = null;
const wifi = () => wf || (wf = Wifi.create(app.getPath('userData'), () => { try { return mobile().identity().name; } catch (e) { return ''; } }));
ipcMain.handle('wifi:status', () => wifi().status());
ipcMain.handle('wifi:set', (e, on) => wifi().set(!!on));
app.whenReady().then(() => { try { if (wifi().wantOn && mobile().wantOn) wifi().start(); } catch (e) { /* switched on again from Settings */ } });
app.on('window-all-closed', () => app.quit());

// ---- folders (backups)
ipcMain.handle('fs:backupDir', () => ensure(BACKUPS()));
ipcMain.handle('fs:pick', async () => { const r = await dialog.showOpenDialog(win, { title: 'فۆڵدەری پاشەکەوت', properties: ['openDirectory', 'createDirectory'] }); return r.canceled ? null : r.filePaths[0]; });
ipcMain.handle('fs:write', async (e, dir, name, text) => { ensure(dir); const f = inside(dir, name), tmp = f + '.part'; await fs.promises.writeFile(tmp, text, 'utf8'); await fs.promises.rename(tmp, f); return true; });
ipcMain.handle('fs:read', (e, dir, name) => fs.promises.readFile(inside(dir, name), 'utf8'));
ipcMain.handle('fs:stat', async (e, dir, name) => { const s = await fs.promises.stat(inside(dir, name)); return { size: s.size, mtime: s.mtimeMs }; });
ipcMain.handle('fs:remove', (e, dir, name) => fs.promises.unlink(inside(dir, name)).catch(() => {}));
ipcMain.handle('fs:list', async (e, dir) => { try { return (await fs.promises.readdir(dir, { withFileTypes: true })).filter(d => d.isFile()).map(d => ({ name: d.name })); } catch (er) { return []; } });
// Google Drive for desktop: its folder (a drive letter, usually G:, holding "My Drive"; or "My Drive" in the user's folder when it
// mirrors). { path } when found, { none: true } when Google Drive is not on this computer, null when unsure (the user picks it)
ipcMain.handle('fs:gdrive', () => {
  if (process.platform !== 'win32') return null;
  const isDir = p => { try { return fs.statSync(p).isDirectory(); } catch (e) { return false; } };
  for (const L of 'DEFGHIJKLMNOPQRSTUVWXYZ') {
    const root = L + ':\\';
    if (!isDir(path.join(root, '.shortcut-targets-by-id')) && !isDir(path.join(root, 'My Drive'))) continue;
    if (isDir(path.join(root, 'My Drive'))) return { path: path.join(root, 'My Drive') };
    let dirs = []; try { dirs = fs.readdirSync(root, { withFileTypes: true }).filter(d => d.isDirectory() && !/^[.$]/.test(d.name) && !/^(Shared drives|Other computers|System Volume Information)$/i.test(d.name)).map(d => d.name); } catch (e) { dirs = []; }
    if (dirs.length === 1) return { path: path.join(root, dirs[0]) };
    return null;   // a Drive in another language with more than one folder: the user picks
  }
  const home = require('os').homedir();
  for (const n of ['My Drive', 'Google Drive']) if (isDir(path.join(home, n))) return { path: path.join(home, n) };
  return { none: true };
});
ipcMain.handle('fs:open', (e, dir) => shell.openPath(dir || BACKUPS()));

// ---- printers: the page is printed as it is shown for printing (same as the browser), straight to the chosen printer
ipcMain.handle('print:list', async () => (await win.webContents.getPrintersAsync()).map(p => ({ name: p.name, displayName: p.displayName, isDefault: !!p.isDefault })));
ipcMain.handle('print:go', (e, o = {}) => new Promise(res => {
  const opts = { silent: !!o.silent, printBackground: true };
  if (o.deviceName) opts.deviceName = o.deviceName;
  win.webContents.print(opts, (ok, error) => res({ ok, error: ok ? null : String(error || '') }));
}));
// notifications: a Windows notification when the app is behind other windows, and the count on the taskbar icon
ipcMain.handle('note:show', (e, o = {}) => {
  try {
    if (!Notification.isSupported()) return false;
    const n = new Notification({ title: String(o.title || 'ToolBox').slice(0, 120), body: String(o.body || '').slice(0, 300), icon: path.join(ROOT, 'build', 'icon.png') });
    n.on('click', () => { if (!win || win.isDestroyed()) return; if (win.isMinimized()) win.restore(); win.show(); win.focus(); win.webContents.send('note:click', String(o.key || '')); });
    n.show(); return true;
  } catch (er) { return false; }
});
ipcMain.handle('note:badge', (e, count, png) => {
  try {
    if (!win || win.isDestroyed()) return false;
    const c = Math.max(0, Number(count) || 0);
    if (process.platform === 'win32') win.setOverlayIcon(c && png ? nativeImage.createFromDataURL(String(png)) : null, c ? `${c} ئاگادارکردنەوە` : '');
    else app.setBadgeCount(c);
    return true;
  } catch (er) { return false; }
});
ipcMain.handle('app:info', () => ({ version: app.getVersion(), data: app.getPath('userData'), backups: BACKUPS() }));

// ---- updating the app page from a file (picked on this computer): the new page is kept in the app-data folder,
// the one that came with the installation is never touched. The newer of the two opens. If the new page does not start, the
// next start goes back to the installed one by itself. The shop's data is not in these files and is never changed by them.
const UPD = () => path.join(app.getPath('userData'), 'update');
const BUNDLED = path.join(ROOT, 'app', 'index.html');
const buildOf = text => { const m = /<meta name="tb-build" content="(\d{12})">/.exec(String(text).slice(0, 4000)); return m ? m[1] : '000000000000'; };
const readBuild = f => { try { const fd = fs.openSync(f, 'r'), b = Buffer.alloc(4000), n = fs.readSync(fd, b, 0, 4000, 0); fs.closeSync(fd); return buildOf(b.slice(0, n).toString('utf8')); } catch (e) { return '000000000000'; } };
const upd = { using: 'bundled', build: '000000000000', bundled: '000000000000', failed: false };
let curPage = BUNDLED;   // the page this window runs (the phones get the same)
function pickPage() {
  const dir = UPD(), cur = path.join(dir, 'index.html'), boot = path.join(dir, 'booting');
  upd.bundled = readBuild(BUNDLED);
  try {
    if (fs.existsSync(boot)) {   // the updated page did not finish starting last time: back to the installed one
      fs.unlinkSync(boot);
      if (fs.existsSync(cur)) { fs.renameSync(cur, path.join(dir, 'failed.html')); upd.failed = true; }
    }
    if (fs.existsSync(cur)) {
      const b = readBuild(cur);
      if (b > upd.bundled) { fs.writeFileSync(boot, '1'); upd.using = 'update'; upd.build = b; curPage = cur; return cur; }
    }
  } catch (e) { /* the installed page */ }
  upd.using = 'bundled'; upd.build = upd.bundled; curPage = BUNDLED; return BUNDLED;
}
const pageOk = t => t.length > 200000 && buildOf(t) !== '000000000000' && /<title>ToolBox<\/title>/.test(t.slice(0, 8000)) && t.includes('const Core = (() =>') && t.includes('ToolBoxHost');
ipcMain.handle('upd:info', () => ({ using: upd.using, build: upd.build, bundled: upd.bundled, failed: upd.failed, hasPrev: fs.existsSync(path.join(UPD(), 'index.prev.html')) }));
ipcMain.handle('upd:check', (e, text) => { text = String(text || ''); return { ok: pageOk(text), build: buildOf(text), cur: upd.build }; });
ipcMain.handle('upd:apply', async (e, text) => {
  text = String(text || '');
  if (!pageOk(text)) return { ok: false, msg: 'bad' };
  const b = buildOf(text); if (b <= upd.build) return { ok: false, msg: 'old', build: b, cur: upd.build };
  const dir = ensure(UPD()), cur = path.join(dir, 'index.html'), tmp = cur + '.part';
  await fs.promises.writeFile(tmp, text, 'utf8');
  if ((await fs.promises.readFile(tmp, 'utf8')).length !== text.length) { await fs.promises.unlink(tmp).catch(() => {}); return { ok: false, msg: 'write' }; }
  if (fs.existsSync(cur)) await fs.promises.rename(cur, path.join(dir, 'index.prev.html'));
  await fs.promises.rename(tmp, cur);
  return { ok: true, build: b };
});
ipcMain.handle('upd:rollback', async () => {
  const dir = UPD(), cur = path.join(dir, 'index.html'), prev = path.join(dir, 'index.prev.html');
  if (upd.using !== 'update') return { ok: false };
  await fs.promises.unlink(cur).catch(() => {});
  if (fs.existsSync(prev)) { if (readBuild(prev) > upd.bundled) await fs.promises.rename(prev, cur); else await fs.promises.unlink(prev).catch(() => {}); }
  return { ok: true };
});
ipcMain.handle('upd:booted', () => { try { fs.unlinkSync(path.join(UPD(), 'booting')); } catch (e) { /* not an updated page */ } upd.failed = false; return true; });
ipcMain.handle('upd:reload', () => { if (win && !win.isDestroyed()) win.loadFile(pickPage()); return true; });

// ---- the Windows part itself from the internet (the page downloads it; the starter checks its signature and opens it on the next
// start). Older pages never ask for this; a newer Windows part keeps every channel the older pages use.
ipcMain.handle('shell:info', () => ({ launcher: TB.launcher, build: TB.build, bundled: TB.bundled, using: TB.using, failed: TB.failed || '', waiting: TB.waiting || '', electron: parseInt(process.versions.electron, 10) || 0 }));
ipcMain.handle('shell:apply', async (e, text) => {
  text = String(text || '');
  const s = TB.check ? TB.check(text) : null;
  if (!s) return { ok: false, msg: 'bad' };
  if (s.build <= TB.build) return { ok: false, msg: 'old' };
  if (s.minLauncher > TB.launcher || s.minElectron > (parseInt(process.versions.electron, 10) || 0)) return { ok: false, msg: 'setup' };
  const dir = ensure(path.join(app.getPath('userData'), 'shell')), f = path.join(dir, `ToolBox-shell-${s.build}.json`), tmp = f + '.part';
  await fs.promises.writeFile(tmp, text, 'utf8');
  if ((await fs.promises.readFile(tmp, 'utf8')) !== text) { await fs.promises.unlink(tmp).catch(() => {}); return { ok: false, msg: 'write' }; }
  await fs.promises.rename(tmp, f);
  return { ok: true, build: s.build };
});
// start again (after a new Windows part): the page has saved everything first
ipcMain.handle('shell:restart', () => { closing = true; app.relaunch(); if (win && !win.isDestroyed()) win.destroy(); app.quit(); return true; });

// ---- the full update (rare: a new Electron or a new starter): a new Setup on the GitHub page's «Releases». It downloads quietly
// (only the parts that changed) and installs when the app is closed, or right away when the page asks. Only the installed app does this.
let fullReady = '';
function fullUpdates() {
  if (!app.isPackaged) return;
  let au = null; try { au = (TB.req || require)('electron-updater').autoUpdater; } catch (e) { return; }   // an installation without it
  au.autoDownload = true; au.autoInstallOnAppQuit = true; au.logger = null;
  au.on('update-downloaded', i => { fullReady = String((i && i.version) || '1'); if (win && !win.isDestroyed()) win.webContents.send('full:ready', fullReady); });
  au.on('error', () => { /* no internet / nothing published: next look */ });
  const look = () => { try { au.checkForUpdates().catch(() => {}); } catch (e) { /* next look */ } };
  setTimeout(look, 60000); setInterval(look, 6 * 3600e3);
  ipcMain.handle('full:install', () => { if (!fullReady) return false; closing = true; setImmediate(() => au.quitAndInstall(true, true)); return true; });
}
ipcMain.handle('full:info', () => ({ version: app.getVersion(), ready: fullReady }));
app.whenReady().then(fullUpdates);

files.preload.js:
// what the app page may ask of Windows — nothing else is reachable from the page
const { contextBridge, ipcRenderer } = require('electron');
let onClose = null, onApi = null, onNote = null, onFull = null;
ipcRenderer.on('full:ready', (e, v) => { try { if (onFull) onFull(v); } catch (er) { /* the page shows it later */ } });
ipcRenderer.on('note:click', (e, key) => { try { if (onNote) onNote(key); } catch (er) { /* nothing to open */ } });
ipcRenderer.on('mob:api', async (e, id, name, d) => {
  let r; try { r = onApi ? await onApi(name, d) : { ok: false, msg: 'ئەپەکە ئامادە نییە' }; } catch (er) { r = { ok: false }; }
  ipcRenderer.send('mob:api-reply', id, r || { ok: false });
});
ipcRenderer.on('app-close', async () => {
  ipcRenderer.send('app-close-seen');
  let ok = true;
  try { if (onClose) ok = (await onClose(() => ipcRenderer.send('app-close-saving'))) !== false; } catch (e) { ok = true; /* the window still closes */ }
  ipcRenderer.send(ok ? 'app-close-ok' : 'app-close-no');
});
contextBridge.exposeInMainWorld('ToolBoxHost', {
  kind: 'windows',
  closeAsk: 2,   // this Windows part waits for the page's question («داخستن» / «مانەوە»)
  info: () => ipcRenderer.invoke('app:info'),
  fs: {
    backupDir: () => ipcRenderer.invoke('fs:backupDir'),
    pickFolder: () => ipcRenderer.invoke('fs:pick'),
    gdrive: () => ipcRenderer.invoke('fs:gdrive'),
    write: (dir, name, text) => ipcRenderer.invoke('fs:write', dir, name, text),
    read: (dir, name) => ipcRenderer.invoke('fs:read', dir, name),
    stat: (dir, name) => ipcRenderer.invoke('fs:stat', dir, name),
    remove: (dir, name) => ipcRenderer.invoke('fs:remove', dir, name),
    list: dir => ipcRenderer.invoke('fs:list', dir),
    open: dir => ipcRenderer.invoke('fs:open', dir)
  },
  printers: () => ipcRenderer.invoke('print:list'),
  print: o => ipcRenderer.invoke('print:go', o),
  // ToolBox on the phones: the shop's network only (the status, and switching it on / off)
  mobile: {
    status: () => ipcRenderer.invoke('mob:status'),
    set: on => ipcRenderer.invoke('mob:set', !!on),
    icons: set => ipcRenderer.invoke('mob:icons', set),
    identity: () => ipcRenderer.invoke('mob:identity'),
    setIdentity: x => ipcRenderer.invoke('mob:setIdentity', x),
    onApi: fn => { onApi = fn; },
    // ToolBox Wi-Fi (this computer's own network for the devices)
    wifi: { status: () => ipcRenderer.invoke('wifi:status'), set: on => ipcRenderer.invoke('wifi:set', !!on) }
  },
  // a new app page from a file (the shop's data is not touched); the newer of it and the installed one opens
  update: {
    info: () => ipcRenderer.invoke('upd:info'),
    check: text => ipcRenderer.invoke('upd:check', text),
    apply: text => ipcRenderer.invoke('upd:apply', text),
    rollback: () => ipcRenderer.invoke('upd:rollback'),
    booted: () => ipcRenderer.invoke('upd:booted'),
    reload: () => ipcRenderer.invoke('upd:reload')
  },
  // the Windows part itself from the internet (opens on the next start)
  shell: {
    info: () => ipcRenderer.invoke('shell:info'),
    apply: text => ipcRenderer.invoke('shell:apply', text),
    restart: () => ipcRenderer.invoke('shell:restart')
  },
  // the full update (a new Setup from GitHub «Releases»): downloaded quietly, installed when the app closes or when asked
  full: {
    info: () => ipcRenderer.invoke('full:info'),
    install: () => ipcRenderer.invoke('full:install'),
    onReady: fn => { onFull = fn; }
  },
  // Windows notifications and the number on the taskbar icon
  notify: {
    show: o => ipcRenderer.invoke('note:show', o),
    badge: (n, png) => ipcRenderer.invoke('note:badge', n, png),
    onClick: fn => { onNote = fn; }
  },
  onClose: fn => { onClose = fn; }
});

files.mobile.js:
// ToolBox on the iPhone / Android (Settings → iPhone): this computer serves the app to the shop's phones over the shop's own network,
// with nothing on the internet. Three parts:
//   • the shop's own certificate: a root made once on this computer (10 years) that each phone trusts once, and the server's
//     certificate signed by it (renewed here by itself, the phones never have to do anything again)
//   • a fixed name, toolbox-xxxx.local, answered on the network (mDNS, as printers and Apple devices do), so the address stays the
//     same when the hotspot or the router gives this computer another number
//   • two small servers: http (only the first step: the certificate and how to trust it) and https (the app itself)
const http = require('http'), https = require('https'), crypto = require('crypto'), dgram = require('dgram'), os = require('os'), fs = require('fs'), path = require('path');

/* ---------------------------------------------------------------- certificates (X.509, written out by hand: no outside library) */
const len = n => { if (n < 128) return Buffer.from([n]); const b = []; while (n) { b.unshift(n & 255); n = Math.floor(n / 256); } return Buffer.from([0x80 | b.length, ...b]); };
const tlv = (tag, ...parts) => { const body = Buffer.concat(parts.map(p => Buffer.isBuffer(p) ? p : Buffer.from(p))); return Buffer.concat([Buffer.from([tag]), len(body.length), body]); };
const seq = (...p) => tlv(0x30, ...p), set = (...p) => tlv(0x31, ...p);
const int = buf => tlv(0x02, buf[0] & 0x80 ? Buffer.concat([Buffer.from([0]), buf]) : buf);
const oid = s => { const a = s.split('.').map(Number), out = [40 * a[0] + a[1]];
  a.slice(2).forEach(v => { const st = [v & 127]; v = Math.floor(v / 128); while (v) { st.unshift((v & 127) | 128); v = Math.floor(v / 128); } out.push(...st); });
  return tlv(0x06, Buffer.from(out)); };
const utf8 = s => tlv(0x0c, Buffer.from(s, 'utf8'));
const octet = b => tlv(0x04, b), bool = v => tlv(0x01, Buffer.from([v ? 0xff : 0]));
const time = d => { const z = n => String(n).padStart(2, '0'), y = d.getUTCFullYear(),
  t = `${z(d.getUTCMonth() + 1)}${z(d.getUTCDate())}${z(d.getUTCHours())}${z(d.getUTCMinutes())}${z(d.getUTCSeconds())}Z`;
  return y < 2050 ? tlv(0x17, Buffer.from(String(y).slice(2) + t)) : tlv(0x18, Buffer.from(y + t)); };
const ALG = seq(oid('1.2.840.113549.1.1.11'), Buffer.from([0x05, 0x00]));   // sha256 with RSA
const nameOf = cn => seq(set(seq(oid('2.5.4.3'), utf8(cn))), set(seq(oid('2.5.4.10'), utf8('ToolBox POS'))));
const ext = (id, critical, value) => seq(oid(id), critical ? bool(true) : Buffer.alloc(0), octet(value));
const pem = der => '-----BEGIN CERTIFICATE-----\n' + der.toString('base64').match(/.{1,64}/g).join('\n') + '\n-----END CERTIFICATE-----\n';
const fromPem = p => Buffer.from(String(p).replace(/-----[^-]+-----/g, '').replace(/\s+/g, ''), 'base64');
const serial = () => { const b = crypto.randomBytes(16); b[0] &= 0x7f; if (!b[0]) b[0] = 1; return b; };
const keyId = spki => crypto.createHash('sha1').update(spki).digest();

function makeCert({ cn, spki, signKey, issuer, issuerSpki, days, ca, dns, ips }) {
  const now = new Date(Date.now() - 3600e3), end = new Date(now.getTime() + days * 864e5);
  const exts = [];
  if (ca) {
    exts.push(ext('2.5.29.19', true, seq(bool(true))));                       // a root: may sign
    exts.push(ext('2.5.29.15', true, tlv(0x03, Buffer.from([0x01, 0x06]))));  // keyCertSign, cRLSign
  } else {
    exts.push(ext('2.5.29.19', true, seq()));                                  // not a root
    exts.push(ext('2.5.29.15', true, tlv(0x03, Buffer.from([0x05, 0xa0]))));  // digitalSignature, keyEncipherment
    exts.push(ext('2.5.29.37', false, seq(oid('1.3.6.1.5.5.7.3.1'))));         // a web server
    const alt = (dns || []).map(n => tlv(0x82, Buffer.from(n, 'ascii'))).concat((ips || []).map(ip => tlv(0x87, Buffer.from(ip.split('.').map(Number)))));
    exts.push(ext('2.5.29.17', false, seq(...alt)));                           // its names (the browser checks these)
    exts.push(ext('2.5.29.35', false, seq(tlv(0x80, keyId(issuerSpki)))));
  }
  exts.push(ext('2.5.29.14', false, octet(keyId(spki))));
  const tbs = seq(tlv(0xa0, int(Buffer.from([2]))), int(serial()), ALG, issuer, seq(time(now), time(end)), nameOf(cn), spki, tlv(0xa3, seq(...exts)));
  const sig = crypto.sign('sha256', tbs, signKey);
  return seq(tbs, ALG, tlv(0x03, Buffer.concat([Buffer.from([0]), sig])));
}
const rsa = () => crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });

/* ---------------------------------------------------------------- the network */
function lan() {   // this computer's addresses on the local network(s), each with its mask; the shop's own network first
  const out = [];
  Object.entries(os.networkInterfaces()).forEach(([name, list]) => (list || []).forEach(a => {
    if (a.family === 'IPv4' && !a.internal && !/^169\.254\./.test(a.address)) out.push({ ip: a.address, mask: a.netmask, name });
  }));
  // a virtual network (VirtualBox, Hyper-V, a VPN…) is never the one the phones are on: last
  const score = a => (/vEthernet|VirtualBox|VMware|Hyper-?V|WSL|Docker|vbox|VPN|Tailscale|ZeroTier|Hamachi|TAP|TUN|Loopback|Bluetooth|Npcap/i.test(a.name) ? -20 : 0)
    + (/Wi-?Fi|Wireless|WLAN|Local Area Connection\*/i.test(a.name) ? 4 : /Ethernet/i.test(a.name) ? 2 : 0)
    + (/^192\.168\.(56|99)\./.test(a.ip) ? -5 : /^(192\.168|10)\./.test(a.ip) || /^172\.(1[6-9]|2\d|3[01])\./.test(a.ip) ? 1 : 0);
  return out.map((a, i) => Object.assign(a, { s: score(a), i })).sort((a, b) => b.s - a.s || a.i - b.i).map(({ ip, mask, name }) => ({ ip, mask, name }));
}
const toN = ip => ip.split('.').reduce((n, x) => n * 256 + Number(x), 0);
const sameNet = (a, b, mask) => (toN(a) & toN(mask)) >>> 0 === (toN(b) & toN(mask)) >>> 0;

/* ---------------------------------------------------------------- the fixed name (mDNS): "who is toolbox-xxxx.local?" → this computer */
function mdns(host) {
  const want = host.toLowerCase();
  const sock = dgram.createSocket({ type: 'udp4', reuseAddr: true });
  const st = { ok: false, err: '', asked: 0 };
  const readName = (b, o) => { const parts = []; let jumped = false, end = o, guard = 0;
    while (o < b.length && guard++ < 64) { const l = b[o];
      if (l === 0) { if (!jumped) end = o + 1; break; }
      if ((l & 0xc0) === 0xc0) { if (!jumped) end = o + 2; o = ((l & 0x3f) << 8) | b[o + 1]; jumped = true; continue; }
      parts.push(b.slice(o + 1, o + 1 + l).toString('utf8')); o += 1 + l; }
    return { name: parts.join('.').toLowerCase(), next: end }; };
  const encName = n => Buffer.concat(n.split('.').map(p => Buffer.concat([Buffer.from([Buffer.byteLength(p)]), Buffer.from(p)])).concat([Buffer.from([0])]));
  const u16 = v => Buffer.from([v >> 8 & 255, v & 255]), u32 = v => Buffer.from([v >>> 24 & 255, v >> 16 & 255, v >> 8 & 255, v & 255]);
  const answer = ip => Buffer.concat([encName(host), u16(1), u16(0x8001), u32(120), u16(4), Buffer.from(ip.split('.').map(Number))]);
  const ipFor = from => { const L = lan(); const m = L.find(a => sameNet(a.ip, from, a.mask)); return (m || L[0] || {}).ip; };
  sock.on('message', (msg, rinfo) => {
    try {
      if (msg.length < 12 || (msg[2] & 0x80)) return;   // only questions
      const id = msg.readUInt16BE(0), qd = msg.readUInt16BE(4); let o = 12, hit = false, qu = false, qsec = null;
      for (let i = 0; i < qd && o < msg.length; i++) {
        const r = readName(msg, o), type = msg.readUInt16BE(r.next), cls = msg.readUInt16BE(r.next + 2);
        if (r.name === want && (type === 1 || type === 255)) { hit = true; qu = !!(cls & 0x8000); qsec = msg.slice(o, r.next + 4); }
        o = r.next + 4;
      }
      if (!hit) return;
      const ip = ipFor(rinfo.address); if (!ip) return;
      st.asked++;
      if (rinfo.port !== 5353) {   // a plain DNS question sent to us: answered back to it, with its id and question
        const hdr = Buffer.concat([u16(id), u16(0x8400), u16(1), u16(1), u16(0), u16(0)]);
        sock.send(Buffer.concat([hdr, qsec, answer(ip)]), rinfo.port, rinfo.address); return;
      }
      const pkt = Buffer.concat([u16(0), u16(0x8400), u16(0), u16(1), u16(0), u16(0), answer(ip)]);
      try { sock.setMulticastInterface(ip); } catch (e) { /* the default one */ }
      sock.send(pkt, 5353, '224.0.0.251');
      if (qu) sock.send(pkt, 5353, rinfo.address);
    } catch (e) { /* a packet we do not read */ }
  });
  sock.on('error', e => { st.ok = false; st.err = String(e && e.code || e); });
  const join = () => lan().forEach(a => { try { sock.addMembership('224.0.0.251', a.ip); } catch (e) { /* joined already */ } });
  sock.bind(5353, () => {
    try { sock.setMulticastTTL(255); } catch (e) { /* default */ }
    join(); st.ok = true;
    // tell the network once that the name is here (phones that asked before hear it at once)
    lan().forEach(a => { try { sock.setMulticastInterface(a.ip); sock.send(Buffer.concat([u16(0), u16(0x8400), u16(0), u16(1), u16(0), u16(0), answer(a.ip)]), 5353, '224.0.0.251'); } catch (e) { /* later */ } });
  });
  const t = setInterval(join, 15000);   // a hotspot / Wi-Fi joined later
  return { st, close() { clearInterval(t); try { sock.close(); } catch (e) { /* closed */ } } };
}

