self.addEventListener('install', e => { e.waitUntil(caches.open(V).then(c => c.add('/').then(() => Promise.all(['/manifest.webmanifest', '/icon-180.png', '/icon-192.png', '/icon-512.png'].map(u => c.add(u).catch(() => {}))))).then(() => self.skipWaiting())); });
