self.addEventListener('fetch', e => {
  const r = e.request; if (r.method !== 'GET') return;
  const u = new URL(r.url); if (u.origin !== location.origin || u.pathname.startsWith('/api/')) return;
  if (r.mode === 'navigate' || u.pathname === '/') {   // the newest from the computer when it answers at once, else the copy kept here
    e.respondWith((async () => {
      const c = await caches.open(V);
      try { const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), 2500); const res = await fetch('/', { signal: ctl.signal, cache: 'no-store' }); clearTimeout(t); if (res.ok) { c.put('/', res.clone()); return res; } } catch (err) { /* no network: the kept copy */ }
      return (await c.match('/')) || Response.error();
