function create(dir, getPage, onApi) {
  const FILE = path.join(dir, 'mobile.json');
  let cfg = {}; try { cfg = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e) { cfg = {}; }
  const save = () => { try { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(FILE + '.part', JSON.stringify(cfg)); fs.renameSync(FILE + '.part', FILE); } catch (e) { /* kept in memory */ } };
  if (!/^toolbox-[a-z0-9]{4}$/.test(cfg.name || '')) { cfg.name = 'toolbox-' + crypto.randomBytes(3).toString('hex').slice(0, 4); save(); }
  const host = () => cfg.name + '.local';
  let S = null;   // { https, http, mdns, ports }
  let appCache = null;   // the app page as the phones get it (made again when the computer's page changes)
  const appNow = () => {
    const pg = getPage ? getPage() : null; if (!pg || !pg.text) return null;
