      if (u === '/manifest.webmanifest') return send(res, 200, 'application/manifest+json; charset=utf-8', MANIFEST);
      const im = /^\/icon-(180|192|512)\.png$/.exec(u);
      if (im) { const b = icon(im[1]); return b ? send(res, 200, 'image/png', b, { 'Cache-Control': 'public, max-age=86400' }) : send(res, 404, 'text/plain', Buffer.from('not found')); }
