    });
    hs.keepAliveTimeout = 5000;
    const ps = http.createServer((req, res) => {
      const u = (req.url || '/').split('?')[0];
      if (req.method === 'GET' && u === '/toolbox-shop.crt') return send(res, 200, 'application/x-x509-ca-cert', fromPem(cfg.caCert), { 'Content-Disposition': 'attachment; filename="toolbox-shop.crt"' });
      if (req.method === 'GET' && u === '/') { const ip = String((req.socket && req.socket.localAddress) || '').replace(/^::ffff:/, ''); return send(res, 200, 'text/html; charset=utf-8', setupPage(appUrl(), cfg.name, /^\d+\.\d+\.\d+\.\d+$/.test(ip) ? `https://${ip}:${st.https.port}/` : appUrl())); }
      send(res, 404, 'text/plain', Buffer.from('not found'));
    });
    const want = n => [n, n + 1, n + 2, n + 3, n + 4];
    S = { hs, ps, md: null };
    try { st.https.port = await listen(hs, cfg.httpsPort ? [cfg.httpsPort].concat(want(8443)) : want(8443)); st.https.ok = true; st.https.err = ''; if (cfg.httpsPort !== st.https.port) { cfg.httpsPort = st.https.port; save(); } }
    catch (e) { st.https.ok = false; st.https.err = String(e.code || e.message); }
    try { st.http.port = await listen(ps, want(8080)); st.http.ok = true; st.http.err = ''; } catch (e) { st.http.ok = false; st.http.err = String(e.code || e.message); }
    try { S.md = mdns(host()); } catch (e) { S.md = { st: { ok: false, err: String(e.message) }, close() {} }; }
    // a new network (ToolBox Wi-Fi, a hotspot, another router): the server's certificate is made again for its address, at once
    S.ct = setInterval(() => { if (!S) return; const was = cfg.leafSig; try { certs(); } catch (e) { return; }
