    let fp = ''; try { fp = new crypto.X509Certificate(cfg.caCert).fingerprint256.replace(/:/g, '').slice(0, 16); } catch (e) { /* not made yet */ }
    return { on: st.on, name: host(), https: Object.assign({}, st.https), http: Object.assign({}, st.http), mdns: S && S.md ? Object.assign({}, S.md.st) : { ok: false, err: '' },
      ips, setupUrls: st.http.ok ? ips.map(ip => `http://${ip}:${st.http.port}/`) : [], appUrl: st.https.ok ? appUrl() : '', ca: fp,
