// ToolBox Wi-Fi (Settings → Devices): this computer makes its own Wi-Fi network for the shop's devices, with no internet needed.
// Windows does it; this file only asks it, through a small PowerShell script that stays open while the network is on:
//   1. Windows' own "Mobile hotspot" (the most reliable), when the computer has any network connection to start it from;
//   2. otherwise Wi-Fi Direct in "access point" mode, which needs no connection at all (most Wi-Fi cards can do it).
// The phones see a normal Wi-Fi network (ToolBox-xxxx + a password); with no internet on it, they keep using their own mobile data.
const { spawn } = require('child_process');
const fs = require('fs'), path = require('path'), crypto = require('crypto');

/* the script: plain ASCII, no backticks; it writes one line of JSON every few seconds and cleans up when asked or when the app is gone */
const SCRIPT = String.raw`
param([string]$Ssid, [string]$Pass, [int]$Parent, [string]$StopFile)
$ErrorActionPreference = 'Stop'
function Out-St($o) { try { [Console]::Out.WriteLine(($o | ConvertTo-Json -Compress)); [Console]::Out.Flush() } catch { } }
function Alive { return [bool](Get-Process -Id $Parent -ErrorAction SilentlyContinue) }
function Asked { return (Test-Path -LiteralPath $StopFile) }
try { Add-Type -AssemblyName System.Runtime.WindowsRuntime } catch { Out-St @{ err = 'winrt'; msg = [string]$_.Exception.Message }; exit 2 }
$ms = [System.WindowsRuntimeSystemExtensions].GetMethods()
$asOp = $ms | Where-Object { $_.Name -eq 'AsTask' -and $_.IsGenericMethodDefinition -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -like 'IAsyncOperation*' } | Select-Object -First 1
$asAct = $ms | Where-Object { $_.Name -eq 'AsTask' -and -not $_.IsGenericMethodDefinition -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncAction' } | Select-Object -First 1
function Await($op, [Type]$t) { $k = $asOp.MakeGenericMethod($t).Invoke($null, @($op)); if (-not $k.Wait(30000)) { throw 'timeout' }; return $k.Result }
function AwaitAct($a) { $k = $asAct.Invoke($null, @($a)); if (-not $k.Wait(30000)) { throw 'timeout' } }

$mode = ''; $lost = 0; $tm = $null; $pub = $null; $lis = $null; $startedHs = $false; $old = $null; $devs = @{}
$RT = $null

# ---- 1. Windows' Mobile hotspot
try {
  $NI = [Windows.Networking.Connectivity.NetworkInformation, Windows.Networking.Connectivity, ContentType = WindowsRuntime]
  $TMT = [Windows.Networking.NetworkOperators.NetworkOperatorTetheringManager, Windows.Networking.NetworkOperators, ContentType = WindowsRuntime]
  $RT = [Windows.Networking.NetworkOperators.NetworkOperatorTetheringOperationResult, Windows.Networking.NetworkOperators, ContentType = WindowsRuntime]
  $prof = $NI::GetInternetConnectionProfile()
  if (-not $prof) { $prof = $NI::GetConnectionProfiles() | Where-Object { [string]$_.GetNetworkConnectivityLevel() -ne 'None' } | Select-Object -First 1 }
  if ($prof -and ([string]$TMT::GetTetheringCapabilityFromConnectionProfile($prof)) -eq 'Enabled') {
    $tm = $TMT::CreateFromConnectionProfile($prof)
    $c = $tm.GetCurrentAccessPointConfiguration()
    if ($c.Ssid -ne $Ssid -or $c.Passphrase -ne $Pass) {
      $old = @{ ssid = $c.Ssid; pass = $c.Passphrase }
      if ([string]$tm.TetheringOperationalState -eq 'On') { [void](Await ($tm.StopTetheringAsync()) $RT) }
      $c.Ssid = $Ssid; $c.Passphrase = $Pass
      AwaitAct ($tm.ConfigureAccessPointAsync($c))
    }
    if ([string]$tm.TetheringOperationalState -ne 'On') {
      $r = Await ($tm.StartTetheringAsync()) $RT
      if ([string]$r.Status -eq 'Success') { $startedHs = $true; $mode = 'hotspot' }
      else { Out-St @{ note = 'hotspot'; v = [string]$r.Status; msg = [string]$r.AdditionalErrorMessage } }
    } else { $mode = 'hotspot' }
  } else { Out-St @{ note = 'hotspot'; v = 'noConnection' } }
} catch { Out-St @{ note = 'hotspot'; v = 'error'; msg = [string]$_.Exception.Message } }

# ---- 2. Wi-Fi Direct as an access point (no connection needed)
if (-not $mode) {
  try {
    [void][Windows.Devices.WiFiDirect.WiFiDirectAdvertisementPublisher, Windows.Devices.WiFiDirect, ContentType = WindowsRuntime]
    [void][Windows.Devices.WiFiDirect.WiFiDirectConnectionListener, Windows.Devices.WiFiDirect, ContentType = WindowsRuntime]
    [void][Windows.Devices.WiFiDirect.WiFiDirectDevice, Windows.Devices.WiFiDirect, ContentType = WindowsRuntime]
    [void][Windows.Security.Credentials.PasswordCredential, Windows.Security.Credentials, ContentType = WindowsRuntime]
    $pub = New-Object Windows.Devices.WiFiDirect.WiFiDirectAdvertisementPublisher
    $adv = $pub.Advertisement
    $adv.IsAutonomousGroupOwnerEnabled = $true
    $ls = $adv.LegacySettings
    $ls.IsEnabled = $true
    $ls.Ssid = $Ssid
    $cred = New-Object Windows.Security.Credentials.PasswordCredential
    $cred.Password = $Pass
    $ls.Passphrase = $cred
    try {
      $lis = New-Object Windows.Devices.WiFiDirect.WiFiDirectConnectionListener
      Register-ObjectEvent -InputObject $lis -EventName ConnectionRequested -SourceIdentifier tbreq | Out-Null
    } catch { $lis = $null }
    $pub.Start()
    Start-Sleep -Milliseconds 1500
    if ([string]$pub.Status -eq 'Started') { $mode = 'direct' }
    else { Out-St @{ err = 'direct'; v = [string]$pub.Status }; exit 3 }
  } catch { Out-St @{ err = 'direct'; v = 'error'; msg = [string]$_.Exception.Message }; exit 3 }
}

# ---- on: report every few seconds; keep it on (Windows turns an empty hotspot off after a while)
try {
  while ((Alive) -and -not (Asked)) {
    if ($mode -eq 'hotspot') {
      $s = [string]$tm.TetheringOperationalState
      if ($s -eq 'Off') { try { $r = Await ($tm.StartTetheringAsync()) $RT; if ([string]$r.Status -eq 'Success') { $startedHs = $true } } catch { } ; $s = [string]$tm.TetheringOperationalState }
      if ($s -eq 'On') { $lost = 0 } else { $lost++ }
      # the connection it was started from is gone (it will not come back on): out, and the app starts again with Wi-Fi Direct
      if ($lost -ge 6) { Out-St @{ err = 'hotspotLost'; v = $s }; break }
      Out-St @{ ok = 1; mode = 'hotspot'; state = $s; clients = [int]$tm.ClientCount }
      for ($i = 0; $i -lt 10 -and (Alive) -and -not (Asked); $i++) { Start-Sleep -Milliseconds 500 }
    } else {
      $e = $null
      if ($lis) { $e = Wait-Event -SourceIdentifier tbreq -Timeout 5 } else { Start-Sleep -Seconds 5 }
      if ($e) {
        try {
          $req = $e.SourceEventArgs.GetConnectionRequest()
          $id = $req.DeviceInformation.Id
          $d = Await ([Windows.Devices.WiFiDirect.WiFiDirectDevice]::FromIdAsync($id)) ([Windows.Devices.WiFiDirect.WiFiDirectDevice])
          if ($d) { $devs[$id] = $d }
        } catch { }
        Remove-Event -EventIdentifier $e.EventIdentifier -ErrorAction SilentlyContinue
      }
      foreach ($k in @($devs.Keys)) { try { if ([string]$devs[$k].ConnectionStatus -ne 'Connected') { $devs.Remove($k) } } catch { $devs.Remove($k) } }
      $st = [string]$pub.Status
      if ($st -ne 'Started') { try { $pub.Start() } catch { } ; $st = [string]$pub.Status }
      Out-St @{ ok = 1; mode = 'direct'; state = $st; clients = $devs.Count }
    }
  }
} finally {
  # off: the hotspot as it was before (its own name and password back), Wi-Fi Direct simply stops
  try { if ($mode -eq 'hotspot' -and $startedHs) { [void](Await ($tm.StopTetheringAsync()) $RT) } } catch { }
  try { if ($mode -eq 'hotspot' -and $old) { $c = $tm.GetCurrentAccessPointConfiguration(); $c.Ssid = $old.ssid; $c.Passphrase = $old.pass; AwaitAct ($tm.ConfigureAccessPointAsync($c)) } } catch { }
  try { if ($pub) { $pub.Stop() } } catch { }
  try { Remove-Item -LiteralPath $StopFile -ErrorAction SilentlyContinue } catch { }
  Out-St @{ off = 1 }
}
`;

function create(dir, nameOf) {
  const FILE = path.join(dir, 'wifi.json'), PS1 = path.join(dir, 'toolbox-wifi.ps1'), STOP = path.join(dir, 'toolbox-wifi.stop');
  let cfg = {}; try { cfg = JSON.parse(fs.readFileSync(FILE, 'utf8')) || {}; } catch (e) { cfg = {}; }
  const save = () => { try { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(FILE + '.part', JSON.stringify(cfg)); fs.renameSync(FILE + '.part', FILE); } catch (e) { /* kept in memory */ } };
  // the password: 10 letters and digits that cannot be mixed up (no 0/o, 1/l/i), made once and kept
  if (!/^[a-z2-9]{10}$/.test(cfg.pass || '')) { const A = 'abcdefghjkmnpqrstuvwxyz23456789'; cfg.pass = [...crypto.randomBytes(10)].map(b => A[b % A.length]).join(''); save(); }
  const ssid = () => 'ToolBox-' + String(nameOf() || 'toolbox-0000').replace(/^toolbox-/, '').replace(/[^a-z0-9]/gi, '').slice(0, 8);

  let ps = null, st = { state: 'off' }, tries = 0, retryT = 0, waiters = [];
  const view = () => ({ supported: process.platform === 'win32', on: !!cfg.on, ssid: ssid(), pass: cfg.pass, mode: st.mode || '', state: st.state || 'off',
    clients: Number(st.clients) || 0, err: st.err || '', msg: st.msg || '', note: st.note || '' });
  const settle = () => { const w = waiters; waiters = []; w.forEach(f => f(view())); };

  function run() {
    if (ps || process.platform !== 'win32') return;
    clearTimeout(retryT);
    try { fs.mkdirSync(dir, { recursive: true }); fs.writeFileSync(PS1, SCRIPT.replace(/\n/g, '\r\n'), 'ascii'); try { fs.unlinkSync(STOP); } catch (e) { /* none */ } }
    catch (e) { st = { state: 'error', err: 'file', msg: String(e.message) }; settle(); return; }
    st = { state: 'starting' };
    const exe = path.join(process.env.SystemRoot || 'C:\\Windows', 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe');
    try {
      ps = spawn(fs.existsSync(exe) ? exe : 'powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', PS1, '-Ssid', ssid(), '-Pass', cfg.pass, '-Parent', String(process.pid), '-StopFile', STOP],
        { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (e) { ps = null; st = { state: 'error', err: 'spawn', msg: String(e.message) }; settle(); return; }
    const me = ps; let buf = '', note = '';
    me.stdout.on('data', d => {
      buf += d.toString('utf8'); let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1); if (!line) continue;
        let o; try { o = JSON.parse(line); } catch (e) { continue; }
        if (o.ok) { st = { mode: o.mode, state: o.state === 'On' || o.state === 'Started' ? 'on' : 'starting', clients: o.clients, note }; tries = 0; settle(); }
        else if (o.err) { st = { state: 'error', err: o.err, msg: [o.v, o.msg].filter(Boolean).join(' · '), note }; settle(); }
        else if (o.note) note = [o.v, o.msg].filter(Boolean).join(' · ');
      }
    });
    me.stderr.on('data', () => { /* the JSON lines say what went wrong */ });
    me.on('error', e => { if (ps === me) { ps = null; st = { state: 'error', err: 'spawn', msg: String(e.message) }; settle(); } });
    me.on('exit', () => {
      if (ps !== me) return; ps = null;
      if (st.state !== 'error') st = { state: cfg.on ? 'error' : 'off', err: cfg.on ? 'stopped' : '', msg: '' };
      settle();
      // still wanted: tried again (a Wi-Fi card switched off and on again, the computer waking up…), a little later each time
      if (cfg.on && tries < 20) { tries++; retryT = setTimeout(run, Math.min(120000, 10000 * tries)); }
    });
  }
  function halt() {
    clearTimeout(retryT); const me = ps; if (!me) { st = { state: 'off' }; return; }
    try { fs.writeFileSync(STOP, '1'); } catch (e) { /* the script also stops when the app is gone */ }
    ps = null; st = { state: 'off' };
    setTimeout(() => { try { me.kill(); } catch (e) { /* ended */ } }, 15000);   // it cleans up on its own within a few seconds
  }
  /** on / off from Settings; the answer waits (up to 20 s) for Windows to say how it went */
  function set(on) {
    cfg.on = !!on; save(); tries = 0;
    if (!on) { halt(); return Promise.resolve(view()); }
    return new Promise(res => { waiters.push(res); setTimeout(() => { waiters = waiters.filter(f => f !== res); res(view()); }, 20000); run(); if (!ps) settle(); });
  }
  return { set, status: view, start() { if (cfg.on) run(); }, close: halt, get wantOn() { return !!cfg.on; } };
}
module.exports = { create, _script: SCRIPT };
